INSERT INTO `events` VALUES (97,'Test Activity 1 Edited','/uploads/activity/Test-Activity-1-Edited-2026-05-18-ph2t3r.png','[{\"title\":\"เงื่อนไขต่างๆ\",\"content\":\"1.ผลงานที่ส่งเข้าประกวดต้องเป็นผลงานที่ผู้สมัครสร้างสรรค์ขึ้นด้วยตนเอง และไม่เคยเผยแพร่ที่ใดมาก่อน\\n2.ห้ามส่งผลงานที่มีเนื้อหาขัดต่อศีลธรรม ความมั่นคง หรือละเมิดลิขสิทธิ์ของผู้อื่น\\n3.ผู้เข้าประกวดสามารถส่งผลงานได้ไม่จำกัดจำนวน แต่จะได้รับรางวัลสูงสุดเพียงรางวัลเดียวเท่านั้น\\n4.ผลงานที่ได้รับรางวัล ถือเป็นสิทธิ์ของทางผู้จัดงานในการนำไปใช้เผยแพร่และประชาสัมพันธ์\\n5.ผู้จัดงานขอสงวนสิทธิ์ในการเปลี่ยนแปลงเงื่อนไขโดยไม่ต้องแจ้งให้ทราบล่วงหน้า\",\"image\":\"/uploads/activity/Test-Activity-1-Edited-section-2026-05-28-0aj9s1.png\"}]',NULL,NULL,NULL,NULL,1,1,1,'08:00:00','17:00:00',0,'กิจกรรม','event',0,0,'Cloud','AI Unit',NULL,NULL,'',NULL,'[\"general\"]','{\"tanita_dates\":[{\"label\":\"เก็บค่าองค์ประกอบของร่างกายครั้งที่ 1\",\"date\":\"2026-05-21\"},{\"label\":\"เก็บค่าองค์ประกอบของร่างกายครั้งที่ 2\",\"date\":\"2026-05-23\"},{\"label\":\"เก็บค่าองค์ประกอบของร่างกายครั้งที่ 3\",\"date\":\"2026-05-25\"}]}','open',NULL,NULL,NULL,'2026-05-15 10:24:22','{\"enabled\":false}','{\"enabled\":false}','{\"pre_test\":{\"enabled\":true},\"post_test\":{\"enabled\":true}}',0);
